-- Datos extraídos de FFCV (scripts/ffcv-equipos.mjs)
-- Clubes de fútbol base, provincia de Valencia | una fila por club+campo
-- Ejecutar en orden. Cada fichero es autónomo.

on conflict (id) do update set
  club = excluded.club,
  escudo = excluded.escudo,
  campo = excluded.campo,
  codigo_campo = excluded.codigo_campo,
  direccion = excluded.direccion,
  localidad = excluded.localidad,
  provincia = excluded.provincia,
  cp = excluded.cp,
  lat = excluded.lat,
  lng = excluded.lng,
  codigo_club = excluded.codigo_club,
  updated_at = excluded.updated_at;

-- Limpieza: elimina filas de corridas anteriores
delete from ffcv_equipos where updated_at < '2026-10-02T13:09:05.387Z';
